  const pb = parse(b);

  for (let i = 0; i < 3; i++) {
    if (pa[i] !== pb[i]) return pa[i] < pb[i] ? -1 : 1;
  }

  const aPre = pa[3];
  const bPre = pb[3];

  if (aPre === undefined && bPre === undefined) return 0;
  if (aPre === undefined) return 1;      // release > pre-release
  if (bPre === undefined) return -1;     // pre-release < release

  const ap = aPre.split('.');
  const bp = bPre.split('.');
  const n = Math.min(ap.length, bp.length);
  for (let i = 0; i < n; i++) {
    const ar = ap[i];
    const br = bp[i];
    const an = /^[\d]+$/.test(ar);
    const bn = /^[\d]+$/.test(br);
    if (an && bn) {
      const c = numCmp(ar, br);
      if (c !== 0) return c;
    } else if (an !== bn) {
      return an ? -1 : 1; // numeric identifiers < non-numeric identifiers
    } else if (ar !== br) {
      return ar < br ? -1 : 1;
    }
  }

  if (ap.length !== bp.length) {     // larger set of fields > smaller set
    return ap.length > bp.length ? 1 : -1;
  }
  return 0;
}

function parse(v) {
  const m = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.\-]+))?$/.exec(String(v));
  if (!m) throw new Error('Invalid semver: ' + v);
  return [Number(m[1]), Number(m[2]), Number(m[3]), m[4]];
}

function numCmp(x, y) {
  const xs = x.replace(/^0+/, '') || '0';
  const ys = y.replace(/^0+/, '') || '0';
  if (xs.length !== ys.length) return xs.length < ys.length ? -1 : 1;
  return xs === ys ? 0 : (xs < ys ? -1 : 1);
}
