        const isNum = /^\d+$/.test(p);
        preParts.push({ isNum, val: isNum ? Number(p) : p });
      }
    }
    return { major, minor, patch, preParts };
  }

  const va = parse(a);
  const vb = parse(b);

  if (va.major !== vb.major) return va.major > vb.major ? 1 : -1;
  if (va.minor !== vb.minor) return va.minor > vb.minor ? 1 : -1;
  if (va.patch !== vb.patch) return va.patch > vb.patch ? 1 : -1;

  if (va.preParts.length === 0 && vb.preParts.length === 0) return 0;
  if (va.preParts.length === 0) return 1;
  if (vb.preParts.length === 0) return -1;

