function compareSemver(a, b) {
  const parse = (v) => {
    const [main, pre = ""] = String(v).split("-", 2);
    const [major, minor, patch] = main.split(".").map(Number);
    return {
      nums: [major, minor, patch],
      preParts: pre.length ? pre.split(".") : [],
    };
  };

  const A = parse(a);
  const B = parse(b);

  // Compare major.minor.patch numerically.
  for (let i = 0; i < 3; i++) {
    if (A.nums[i] !== B.nums[i]) {
      return A.nums[i] > B.nums[i] ? 1 : -1;
    }
  }

  // Pre-release presence: a version without a pre-release is higher.
  const hasA = A.preParts.length > 0;
  const hasB = B.preParts.length > 0;
  if (!hasA && !hasB) return 0;
  if (!hasA) return 1;
  if (!hasB) return -1;

  // Compare pre-release identifiers.
  const len = Math.min(A.preParts.length, B.preParts.length);
  for (let i = 0; i < len; i++) {
    const pa = A.preParts[i];
    const pb = B.preParts[i];
    const numA = /^\d+$/.test(pa);
    const numB = /^\d+$/.test(pb);

    let cmp;
    if (numA && numB) {
      const na = parseInt(pa, 10);
      const nb = parseInt(pb, 10);
      cmp = na > nb ? 1 : na < nb ? -1 : 0;
    } else if (numA !== numB) {
      // Numeric identifiers always have lower precedence than non-numeric.
      cmp = numA ? -1 : 1;
    } else {
      cmp = pa < pb ? -1 : pa > pb ? 1 : 0;
    }

    if (cmp !== 0) return cmp;
  }

  // If all shared identifiers are equal, a larger set has higher precedence.
  if (A.preParts.length !== B.preParts.length) {
    return A.preParts.length > B.preParts.length ? 1 : -1;
  }

  return 0;
}
